function DiscoveryPollCard({ compact = false }: { compact?: boolean }) {
  const [selected,setSelected] = useState<string | null>(null);
  const total = discoveryOptions.reduce((sum,o)=>sum+o.votes,0) + (selected ? 1 : 0);
  return <div className={`rounded-[1.6rem] border border-[#ff6a00]/25 bg-[#0d0d0e] ${compact?"p-5":"p-6"}`}><div className="flex items-center justify-between"><MarkLabel kind="explore">Discovery</MarkLabel><Vote className="h-5 w-5 text-[#ff6a00]"/></div><h3 className="mt-3 font-serif text-2xl font-bold">What should Kingston get next?</h3><p className="mt-2 text-sm text-white/45">Your signal helps show where demand is forming.</p><div className="mt-4 space-y-2">{discoveryOptions.map(option=><button type="button" key={option.id} onClick={()=>setSelected(option.id)} className={`w-full rounded-xl border px-4 py-3 text-left text-sm font-bold ${selected===option.id?"border-[#ff6a00] bg-[#ff6a00]/10":"border-white/10"}`}>{option.label}</button>)}</div><div className="mt-4 flex items-center justify-between text-xs text-white/42"><span>{total.toLocaleString()} signals</span><Link to="/discover/poll" className="font-bold text-[#ff9a4d]">Open poll →</Link></div></div>;
}

